            return r
        store._write_atomic = wrapped

    if crashpoint == "after_phase1":
        def fake_append(event):
            if event.action == audit_mod.ACTION_BATCH_ROTATE:
                _kill()
            return store_mod.KeyStore.__mro__ and store.audit.__class__.append(
                store.audit, event
            )
        store.audit.append = fake_append

    if crashpoint == "after_commit":
        real_append = store.audit.append
        def wrapped_append(event):
            r = real_append(event)
            if event.action == audit_mod.ACTION_BATCH_ROTATE:
                _kill()
            return r
        store.audit.append = wrapped_append

    if crashpoint == "finalize_partial":
        orig_write = store._write_atomic
        state = {"cleared": 0}
        def wrapped(path, payload):
            r = orig_write(path, payload)
            if isinstance(payload, dict) and (
                payload.get("pending_event") is None
            ) and os.path.basename(path) in (ids[0] + ".json", ids[1] + ".json"):
                state["cleared"] += 1
                if state["cleared"] == 1:
                    _kill()
            return r
        store._write_atomic = wrapped

    try:
        status, result = store.batch_rotate(
            "tenant-a", items, event_id=rec.operation_id, pre_commit=pre_commit
        )
        print(json.dumps({"status": "returned", "result": status}))
    except BaseException as exc:
        print(json.dumps({"status": "raised", "error": type(exc).__name__}))


def inspect(data_dir, ids):
    store = make_store(data_dir)
    out = {"keys": {}, "artifacts": {}, "events": [], "mutations": {}}
    for kid in ids:
        rec = store.get(kid, "tenant-a")
        out["keys"][kid] = (
            None if rec is None
            else {"current": rec.current_version}
        )
    bdir = os.path.join(data_dir, "batch-rotations")
    pdir = os.path.join(data_dir, "provisions")
    out["artifacts"]["snapshots"] = (
        os.listdir(bdir) if os.path.isdir(bdir) else []
    )
    out["artifacts"]["journals"] = (
        os.listdir(pdir) if os.path.isdir(pdir) else []
    )
    # Markers on disk.
    markers = {}
    for kid in ids:
        raw = store.read_raw(kid)
        pe = getattr(raw, "pending_event", None)
        if pe:
            markers[kid] = {"batch": bool(pe.get("_batch_rotate"))}
    out["markers"] = markers
    # Audit events.
    for ev in store.audit._read_all():
        if ev.action == "batch_rotate":
            out["events"].append({"id": ev.event_id, "outcome": ev.outcome})
    # Provider registry handles.
    reg_path = os.path.join(data_dir, "local-registry.json")
    if os.path.exists(reg_path):
        with open(reg_path) as fh:
            out["registry_count"] = len(json.load(fh))
    # Mutation blocking: rotate / revoke must 503 while parked.
    from keymgr.provider import ProviderUnavailable
    for action in ("rotate", "revoke", "batch"):
        try:
            if action == "rotate":
                store.rotate(ids[0], "tenant-a", "AES256")
            elif action == "revoke":
                store.revoke(ids[0], "tenant-a", "r", "alice")
            else:
                store.batch_rotate("tenant-a", items=[(ids[0], "AES256")])
            out["mutations"][action] = "succeeded"
        except ProviderUnavailable:
            out["mutations"][action] = "503"
        except Exception as exc:
            out["mutations"][action] = type(exc).__name__
    print(json.dumps(out, indent=1, sort_keys=True))


def recover_op(data_dir, ids):
    """Reopen (store recovery) then settle pending operations."""
    from keymgr.audit import AuditLog
    from keymgr.operations import OperationStore
    from keymgr.policy import PolicyStore
    from keymgr.restore import RestoreCoordinator
    from keymgr.store import KeyStore

    audit = AuditLog(data_dir)
    store = KeyStore(data_dir, audit)
    policies = PolicyStore(data_dir, audit)
    RestoreCoordinator(store, policies)
    ops = OperationStore(data_dir, audit)
    ops.recover_pending(lambda r, e: (201, {"operation_id": r.operation_id}))
    # Report pending ops and their terminals.
    results = []
    d = os.path.join(data_dir, "operations")
    for name in os.listdir(d):
        if name.endswith(".json") and name != "index.json":
            rec = ops._read_record(name[:-5])
            if rec:
                results.append({
                    "id": rec.operation_id,
                    "status": rec.status,
                    "http": rec.http_status,
                })
    print(json.dumps({"operations": results}, sort_keys=True))


def tamper_snapshot(data_dir, mode):
    bdir = os.path.join(data_dir, "batch-rotations")
    name = [n for n in os.listdir(bdir) if n.endswith(".json")][0]
    path = os.path.join(bdir, name)
    if mode == "corrupt":
        with open(path, "w") as fh:
            fh.write("{not json")
    elif mode == "delete":
        os.unlink(path)
    elif mode == "badkeys":
        with open(path) as fh:
            doc = json.load(fh)
        doc["keys"][0]["key_id"] = doc["keys"][0]["key_id"].replace("a", "b", 1)
        with open(path, "w") as fh:
            json.dump(doc, fh)
    elif mode == "badimg":
        with open(path) as fh:
            doc = json.load(fh)
        # Tamper the base64 image bytes.
        e = doc["keys"][0]
        raw = bytearray(base64.b64decode(e["previous_b64"]))
        raw[-1] ^= 0xFF
        e["previous_b64"] = base64.b64encode(bytes(raw)).decode()
        with open(path, "w") as fh:
            json.dump(doc, fh)
    print("tampered:%s" % mode)


def main():
    data_dir = sys.argv[1]
    cmd = sys.argv[2]
    if cmd == "setup":
        setup(data_dir)
    elif cmd == "batch":
        ids = json.loads(sys.argv[3])
        crashpoint = sys.argv[4]
        batch(data_dir, ids, crashpoint)
    elif cmd == "inspect":
        ids = json.loads(sys.argv[3])
        inspect(data_dir, ids)
    elif cmd == "recover":
        ids = json.loads(sys.argv[3])
        recover_op(data_dir, ids)
    elif cmd == "tamper":
        tamper_snapshot(data_dir, sys.argv[3])


if __name__ == "__main__":
    main()

