"""Crash/fault injection harness for batch-rotate recovery (throwaway)."""
import base64
import hashlib
import json
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))


def _fault_cfg():
    cfg_path = os.environ.get("CRASH_FAULT_CFG")
    if cfg_path and os.path.exists(cfg_path):
        with open(cfg_path) as fh:
            return json.load(fh)
    return {}


def _install_faults(data_dir):
    """Wrap the local-provider singleton to inject rotate/delete faults."""
    import keymgr.provider as pm

    cfg = _fault_cfg()
    if not cfg:
        return
    local = pm.configure_local(data_dir)
    if getattr(local, "_fault_wrapped", False):
        return
    if cfg.get("raise_rotate"):
        def boom_rotate(algorithm):
            raise pm.ProviderUnavailable("injected rotate failure")
        local.rotate = boom_rotate
    if cfg.get("fail_delete_all") or cfg.get("fail_delete_handles"):
        orig_delete = local.delete
        bad = set(cfg.get("fail_delete_handles") or [])
        def boom_delete(handle):
            if cfg.get("fail_delete_all") or handle in bad:
                raise RuntimeError("injected delete failure")
            return orig_delete(handle)
        local.delete = boom_delete
    local._fault_wrapped = True


def make_store(data_dir):
    from keymgr.audit import AuditLog
    from keymgr.store import KeyStore

    _install_faults(data_dir)
    return KeyStore(data_dir, AuditLog(data_dir))


def setup(data_dir):
    store = make_store(data_dir)
    ids = []
    for i in range(2):
        rec = store.create("tenant-a", "AES256", "k%d" % i)
        ids.append(rec.key_id)
    print(json.dumps(ids))


def _kill():
    sys.stdout.flush()
    os._exit(0)


def batch(data_dir, ids, crashpoint):
    from keymgr import audit as audit_mod
    from keymgr.operations import OperationStore

    os.environ["KEYMGR_DATA_DIR"] = data_dir
    store = make_store(data_dir)
    audit = store.audit
    items = [(kid, "AES256") for kid in ids]

    ops = OperationStore(data_dir, audit)
    rec = ops.begin(
        "tenant-a", "alice", "/v1/keys/batch-rotate",
        json.dumps({"tenant_id": "tenant-a",
                    "items": [{"key_id": k, "algorithm": "AES256"}
                              for k in ids]}, sort_keys=True, separators=(",", ":")),
        "idem-crash",
    ).record

    def pre_commit(records_by_id):
        ops.stage_terminal(rec, 201, {
            "items": [
                {"key_id": k,
                 "version": records_by_id[k].current.version,
                 "algorithm": records_by_id[k].current.algorithm,
                 "public_key": records_by_id[k].current.public_key}
                for k in ids
            ],
            "operation_id": rec.operation_id,
        })

    if crashpoint == "journal_only":
        orig = store._new_provision_journal
        def wrapped(jid):
            r = orig(jid)
            _kill()
            return r
        store._new_provision_journal = wrapped

    if crashpoint == "after_snapshot":
        orig = store._write_batch_snapshot
        def wrapped(*a, **kw):
            r = orig(*a, **kw)
            _kill()
            return r
        store._write_batch_snapshot = wrapped

    if crashpoint == "mid_phase1":
        orig_write = store._write_atomic
        state = {"marked": 0}
        def wrapped(path, payload):
            r = orig_write(path, payload)
            if isinstance(payload, dict) and isinstance(
                payload.get("pending_event"), dict
            ) and payload["pending_event"].get("_batch_rotate"):
                state["marked"] += 1
                if state["marked"] == 1:
                    _kill()
            return r
        store._write_atomic = wrapped

    if crashpoint == "at_append":
        real_append = store.audit.append
        def fake_append(event):
            if event.action == audit_mod.ACTION_BATCH_ROTATE:
                _kill()
            return real_append(event)
        store.audit.append = fake_append

    if crashpoint == "after_commit":
        real_append = store.audit.append
        def wrapped_append(event):
            r = real_append(event)
            if event.action == audit_mod.ACTION_BATCH_ROTATE:
                _kill()
            return r
        store.audit.append = wrapped_append

    try:
        status, result = store.batch_rotate(
            "tenant-a", items, event_id=rec.operation_id, pre_commit=pre_commit
        )
        print(json.dumps({"status": "returned", "result": status}))
    except BaseException as exc:
        print(json.dumps({"status": "raised", "error": type(exc).__name__}))


def inspect(data_dir, ids):
    """Read-only inspection: projections, markers, artifacts, events."""
    store = make_store(data_dir)
    out = {"keys": {}, "raw": {}, "hashes": {}, "artifacts": {},
           "events": [], "markers": {}}
    for kid in ids:
        rec = store.get(kid, "tenant-a")
        out["keys"][kid] = None if rec is None else {"current": rec.current_version}
        raw = store.read_raw(kid)
        out["raw"][kid] = None if raw is None else {
            "current": raw.current_version,
            "marker": bool(getattr(raw, "pending_event", None)),
        }
        path = os.path.join(data_dir, kid + ".json")
        if os.path.exists(path):
            with open(path, "rb") as fh:
                out["hashes"][kid] = hashlib.sha256(fh.read()).hexdigest()[:12]
    bdir = os.path.join(data_dir, "batch-rotations")
    pdir = os.path.join(data_dir, "provisions")
    out["artifacts"]["snapshots"] = os.listdir(bdir) if os.path.isdir(bdir) else []
    out["artifacts"]["journals"] = os.listdir(pdir) if os.path.isdir(pdir) else []
    for ev in store.audit._read_all():
        if ev.action == "batch_rotate":
            out["events"].append({"id": ev.event_id, "outcome": ev.outcome})
    reg_path = os.path.join(data_dir, "local-registry.json")
    if os.path.exists(reg_path):
        with open(reg_path) as fh:
            out["registry_count"] = len(json.load(fh))
    print(json.dumps(out, indent=1, sort_keys=True))


def probe(data_dir, ids):
    """Attempt rotate/revoke/batch against key 0; report outcomes only."""
    from keymgr.provider import ProviderUnavailable
    from keymgr.store import LockTimeout

    store = make_store(data_dir)
    results = {}
    for action in ("rotate", "revoke", "batch"):
        try:
            if action == "rotate":
                store.rotate(ids[0], "tenant-a", "AES256")
            elif action == "revoke":
                store.revoke(ids[0], "tenant-a", "r", "alice")
            else:
                store.batch_rotate("tenant-a", [(ids[0], "AES256")])
            results[action] = "succeeded"
        except ProviderUnavailable:
            results[action] = "503"
        except LockTimeout:
            results[action] = "timeout"
        except Exception as exc:
            results[action] = type(exc).__name__
    print(json.dumps(results, sort_keys=True))


def recover_op(data_dir):
    """Reopen (store recovery) then settle pending operations."""
    from keymgr.audit import AuditLog
    from keymgr.operations import OperationStore
    from keymgr.policy import PolicyStore
    from keymgr.restore import RestoreCoordinator
    from keymgr.store import KeyStore

    audit = AuditLog(data_dir)
    store = KeyStore(data_dir, audit)
    policies = PolicyStore(data_dir, audit)
    RestoreCoordinator(store, policies)
    ops = OperationStore(data_dir, audit)
    ops.recover_pending(lambda r, e: (201, {"operation_id": r.operation_id}))
    results = []
    d = os.path.join(data_dir, "operations")
    for name in os.listdir(d):
        if name.endswith(".json") and name != "index.json":
            rec = ops._read_record(name[:-5])
            if rec:
                results.append({"id": rec.operation_id, "status": rec.status,
                                "http": rec.http_status})
    print(json.dumps({"operations": results}, sort_keys=True))


def tamper_snapshot(data_dir, mode):
    bdir = os.path.join(data_dir, "batch-rotations")
    name = [n for n in os.listdir(bdir) if n.endswith(".json")][0]
    path = os.path.join(bdir, name)
    if mode == "corrupt":
        with open(path, "w") as fh:
            fh.write("{not json")
    elif mode == "delete":
        os.unlink(path)
    elif mode == "badkeys":
        with open(path) as fh:
            doc = json.load(fh)
        target = doc["keys"][0]["key_id"]
        swapped = target.replace("a", "b", 1)
        if swapped == target:
            swapped = target[:-1] + ("0" if target[-1] != "0" else "1")
        doc["keys"][0]["key_id"] = swapped
        with open(path, "w") as fh:
            json.dump(doc, fh)
    elif mode == "badimg":
        with open(path) as fh:
            doc = json.load(fh)
        e = doc["keys"][0]
        raw = bytearray(base64.b64decode(e["previous_b64"]))
        # Flip a byte inside the JSON payload (after first 40 bytes).
        idx = min(40, len(raw) - 1)
        raw[idx] ^= 0x01
        e["previous_b64"] = base64.b64encode(bytes(raw)).decode()
        with open(path, "w") as fh:
            json.dump(doc, fh)
    print("tampered:%s" % mode)


def tamper_marker(data_dir, mode):
    """Corrupt a surviving _batch_rotate marker's references."""
    store = make_store(data_dir)
    for name in os.listdir(data_dir):
        if not (name.endswith(".json") and len(name) == 41):
            continue
        path = os.path.join(data_dir, name)
        rec = store._read_record(path)
        marker = getattr(rec, "pending_event", None)
        if isinstance(marker, dict) and marker.get("_batch_rotate"):
            if mode == "journal_ref":
                marker["journal"] = "00000000-0000-4000-8000-000000000000"
            elif mode == "action":
                marker["event"]["action"] = "rotate"
            elif mode == "tenant":
                marker["event"]["tenant_id"] = "other-tenant"
            elif mode == "keyset":
                marker["key_ids"].pop()
            rec.pending_event = marker
            store._write_atomic(path, rec.to_json())
            print("tampered-marker:%s" % mode)
            return


def forge_ledger_event(data_dir, action, tenant_id):
    """Append a success event with the batch id but wrong action/tenant."""
    bdir = os.path.join(data_dir, "batch-rotations")
    eid = [n[:-5] for n in os.listdir(bdir) if n.endswith(".json")][0]
    from keymgr.audit import AuditEvent
    store = make_store(data_dir)
    ev = AuditEvent(
        event_id=eid, tenant_id=tenant_id, action=action, key_id=None,
        outcome="success", timestamp="2020-01-01T00:00:00+00:00",
    )
    store.audit.append(ev)
    print("forged-event:%s/%s" % (action, tenant_id))


def write_cfg(path, cfg):
    with open(path, "w") as fh:
        json.dump(cfg, fh)


def main():
    data_dir = sys.argv[1]
    cmd = sys.argv[2]
    if cmd == "setup":
        setup(data_dir)
    elif cmd == "batch":
        batch(data_dir, json.loads(sys.argv[3]), sys.argv[4])
    elif cmd == "inspect":
        inspect(data_dir, json.loads(sys.argv[3]))
    elif cmd == "probe":
        probe(data_dir, json.loads(sys.argv[3]))
    elif cmd == "recover":
        recover_op(data_dir)
    elif cmd == "tamper":
        tamper_snapshot(data_dir, sys.argv[3])
    elif cmd == "tamper_marker":
        tamper_marker(data_dir, sys.argv[3])
    elif cmd == "forge":
        forge_ledger_event(data_dir, sys.argv[3], sys.argv[4])
    elif cmd == "cfg":
        write_cfg(sys.argv[3], json.loads(sys.argv[4]))


if __name__ == "__main__":
    main()

