            elif mode == "tenant":
                marker["event"]["tenant_id"] = "other-tenant"
            elif mode == "keyset":
                marker["key_ids"].pop()
            rec.pending_event = marker
            store._write_atomic(path, rec.to_json())
            print("tampered-marker:%s" % mode)
            return

